-- Class notes synopsis batch 7: Chaparral through Cleavers

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chaparral</strong> (Larrea tridentata, Creosote Bush), using leaves and twigs (leaves have the sticky resin), is a broadly <strong>antimicrobial</strong>, <strong>antifungal</strong>, <strong>antioxidant</strong>, and <strong>anti-inflammatory</strong> first aid plant applied externally as tincture, liniment, oil, or tea compress. Indicated for <strong>cuts and open wounds</strong>, <strong>infected wounds</strong>, <strong>animal bites</strong>, and <strong>cellulitis</strong> (tea compresses); used as a primary topical in wound kits alongside <a href="?herb=99"><strong>Myrrh</strong></a> and <a href="?herb=33"><strong>Oregon Grape</strong></a> as antimicrobials, antioxidants, and immune stimulants - sometimes standalone; also an antioxidant for <strong>chronic skin conditions</strong>. Preparation: fresh 1:2 80-95%; dry 1:5 60%. <strong>Beware - hard on liver.</strong>$$
WHERE common_name = 'Chaparral';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chasteberry</strong> (Vitex agnus-castus) is a <strong>drying</strong> <strong>dopamine agonist</strong> that targets the <strong>pituitary</strong>, stimulating FSH and LH release, downregulating excess <strong>prolactin</strong>, nourishing <strong>progesterone</strong> production, and promoting a sense of safety for ovulation; binds opiate receptor sites without sedation; acts via dopamine activity on the hypothalamic-pituitary axis; may take 6 months to a year to effect. Indicated for <strong>amenorrhea</strong> (establishes bi-phasic cycle), <strong>menorrhagia</strong> (confirms ovulation, reduces flow), <strong>PCOS</strong> (luteal support when cycles lengthen or become fewer per year; use weeks 3-4 for pregnancy attempts), <strong>fibroids</strong> (estrogen balance), <strong>fertility support</strong>, and <strong>hormonally induced symptoms</strong>; stimulates HPA for <strong>female reproductive deficiency</strong> and acts as an anabolic cooler for <strong>female reproductive excess</strong>. "Vitex nourishes the Parasympathetic NS, relaxing." Vitex will give life to the luteal phase as long as the body has capacity for it. In bi-phasic protocols, rotate with <a href="?herb=1009"><strong>Dong Quai</strong></a> bi-weekly (Dong Quai 2 weeks for follicular phase, Vitex 2 weeks for luteal phase). Dosage: tincture 1-2 ml 3x/day or 30-60 drops once in the morning; infusion 1 tsp berries in 8 oz water; tincture preferred over tea due to intense flavor. <strong>Caution: may interact with dopamine antagonists.</strong> In Lisa's reproductive formula: Vitex 30 drops (30 mL), <a href="?herb=2238"><strong>White Peony</strong></a> 55 drops (30 mL), <a href="?herb=78"><strong>Licorice</strong></a> 20 drops (25 mL), <a href="?herb=44"><strong>Yarrow</strong></a> 30 drops (35 mL); 2 dropper-fulls 3x/day (total 120 mL). In a hormonal support formula (2 tsp 3x/day) with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, and <a href="?herb=167"><strong>Cinnamon</strong></a>.$$
WHERE common_name = 'Chasteberry';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chickweed</strong> (Stellaria media) is a <strong>cooling</strong>, <strong>demulcent</strong>, <strong>anti-inflammatory</strong>, <strong>vulnerary</strong>, <strong>lymphatic</strong>, and <strong>salty</strong> herb. Topically for <strong>minor skin irritations</strong>, <strong>itchy skin</strong>, <strong>rash</strong>, and <strong>sunburn</strong> - best as infused oil or salve; tincture not recommended for skin use (alcohol is drying). Chickweed oil: <strong>cooling</strong>, <strong>antipruritic</strong>; let wilt for a day, use half-dry half-fresh (one of few fresh plant oils). Internally soothing to <strong>mucous membranes</strong>. A <strong>vulnerary</strong> in wound wash alongside <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=2437"><strong>Self Heal</strong></a>, and <a href="?herb=81"><strong>St. John's Wort</strong></a>. A <strong>lymphatic</strong> for overall immune support.$$
WHERE common_name = 'Chickweed';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chicory</strong> root is a <strong>bitter digestive</strong> and <strong>detox</strong> support used in tea blends for <strong>chemical sensitivity</strong> cases; listed as a <strong>liver alterative</strong> for <strong>hot constitution</strong> alongside <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=40"><strong>Sarsaparilla</strong></a>, <a href="?herb=313"><strong>Sassafras</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=225"><strong>Astragalus</strong></a>.$$
WHERE common_name = 'Chicory';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chinese Skullcap</strong> (Baical/Baikal Skullcap, Scutellaria baicalensis) is an <strong>antiviral</strong>, <strong>mast cell stabilizer</strong>, and <strong>apoptosis-promoting</strong> herb, distinct from American Skullcap. Used in Steven Buehner's protocol for <strong>long covid</strong> and <strong>stealth viruses</strong> - in long covid, cilia desiccate, mast cells lock down, and amyloid plaque enters the bloodstream causing achy body and chronic pain. A <strong>mast cell stabilizer</strong> for <strong>eczema</strong> - reduces allergic response in the skin; and an <strong>immune modulator</strong> for <strong>autoimmune</strong> conditions (lymph/immune excess) to cool <strong>mast cell activation</strong>. In David Hoffmann's <strong>psoriasis</strong> prescription - also add <a href="?herb=983"><strong>Blue Vervain</strong></a> if anxiety present; if no change in tissue, add <a href="?herb=35"><strong>Poke Root</strong></a> 1 drop increasing, with <a href="?herb=40"><strong>Sarsaparilla</strong></a> to buffer. For <strong>Hot Damp Diarrhea</strong>. For <strong>influenza</strong>: antiviral in overall immune support. Promotes <strong>apoptosis</strong>.$$
WHERE common_name = 'Chinese Skullcap';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chinese Yam</strong> (Dioscorea opposita / Shan Yao) increases <strong>insulin sensitivity</strong>.$$
WHERE common_name = 'Chinese Yam';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cinnamon</strong> (Cinnamomum verum, Ceylon - preferred for medicinal effects) is a <strong>warming</strong>, <strong>carminative</strong>, <strong>circulatory tonic</strong>, <strong>diaphoretic</strong>, <strong>immunoregulatory</strong>, <strong>astringent</strong> (tannin-rich, toning and tightening, with a pulling/drawing and drying effect), <strong>hemostatic</strong>, and <strong>hypoglycemic</strong>/<strong>hypolipidemic</strong> herb; also <strong>demulcent</strong> and mucilaginous as a cold infusion - "low-key adaptogenic," slowing transit time and allowing better nutrient absorption; contains eugenol (<strong>anti-inflammatory</strong>); described as fiery in glycerite tasting. Ellingwood: "decoction for post-partum depression, atonic conditions, for someone who has not given birth, general flaccid state after delivery." A key herb for <strong>blood sugar dysregulation</strong>: increases beta cell ability to utilize endogenous insulin, reduces <strong>A1C</strong>, lowers LDL cholesterol, lowers VLDL and triglyceride levels, and is <strong>hypotensive</strong>; appropriate for <strong>insulin-resistant diabetes</strong>, <strong>hyperinsulinemia</strong>, <strong>metabolic syndrome</strong>, <strong>PCOS</strong>, <strong>PMOS</strong>, and <strong>nonalcoholic fatty liver disease</strong>; pair with <a href="?herb=2232"><strong>Gymnema</strong></a>, <a href="?herb=2556"><strong>Bitter Melon</strong></a>, and <a href="?herb=2233"><strong>Hibiscus</strong></a> for Type 2 Diabetes. <strong>Immunoregulatory</strong> for <strong>allergies</strong>, <strong>Crohn's disease</strong>, and <strong>ulcerative colitis</strong>; promotes <strong>tissue regeneration</strong> and increases blood circulation. As a <strong>reproductive tonic</strong>: adaptogenic for <strong>uterine tissues</strong>, nourishing, moistening, tonifying, and warming to the circulatory process in the uterus - for <strong>amenorrhea</strong> (blood sugar regulation and uterine tone), <strong>menorrhagia</strong> (reduces flow in the moment; strong decoction or 1 drop EO under tongue in emergency), <strong>postpartum hemorrhage</strong>, loss of <strong>uterine tone</strong>, and <strong>fibroids</strong>; classic for postpartum support; in reproductive tincture for thyroid/Hashimoto's case with peony, burdock, licorice, gotu kola. For GI: <strong>carminative</strong> for <strong>hypochlorhydria</strong>; warming digestive for rekindling digestive fire; <strong>astringent</strong> for <strong>Cold Damp Diarrhea</strong>; good for both lower GI deficiency and excess; slows peristalsis - use <a href="?herb=124"><strong>Ginger</strong></a> instead if warming digestive support is needed without this slowing effect; inhibits <strong>H. pylori</strong> (<strong>peptic ulcer</strong>); in antispasmodic blend for diarrhea alongside <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=55"><strong>Peppermint</strong></a>, and <a href="?herb=124"><strong>Ginger</strong></a>. For <strong>heart bypass support</strong>: calming and nervine. For <strong>poor circulation</strong>, <strong>slow digestion</strong>, <strong>stiffness</strong>, and <strong>constipation</strong>. Listed as a spice for Wet and Cold constitutions. <strong>Drying - caution with severe constipation; pair with moistening herbs like flaxseed, marshmallow, or chia. Synergistic with Pioglitazone (Actos) - could allow for lower dosage of medication. Hazardous as EO/hydrosol on skin - causes skin irritation.</strong> Dosage: tincture 1 ml TID (or 20-50 drops 4x/day); tea 1/4-1/2 tsp powdered bark in 8 oz water 3x/day; 1-2 00 capsules BID; 1 drop EO under tongue for acute uterine bleeding. In PCOS formula: <a href="?herb=33"><strong>Oregon Grape</strong></a> 30ml, <a href="?herb=78"><strong>Licorice</strong></a> 10ml, <a href="?herb=2238"><strong>White Peony</strong></a> 30ml, Cinnamon 20ml, <a href="?herb=2229"><strong>Gotu Kola</strong></a> 30ml; 4ml 2x/day. In hormonal support formula (2 tsp 3x/day) with <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>. In sleep formula: 1/2 tsp <a href="?herb=20"><strong>Ashwagandha</strong></a> powder with <a href="?herb=127"><strong>Cardamom</strong></a> and nutmeg at night. Used with <a href="?herb=45"><strong>Marshmallow</strong></a> to add warmth to the cooling marshmallow; in marshmallow root blend with Cinnamon and <a href="?herb=20"><strong>Ashwagandha</strong></a> for gut inflammation. In daily tea: 5p <a href="?herb=45"><strong>Marshmallow</strong></a> leaf, 4p <a href="?herb=61"><strong>Mullein</strong></a>, 3p <a href="?herb=90"><strong>Linden</strong></a>, 2p rose, 1p Cinnamon. In heart decoction (to 32 oz water): 28g <a href="?herb=73"><strong>Hawthorn</strong></a> berries, 28g rose hips, 14g Cinnamon. In a tincture with <a href="?herb=145"><strong>Valerian</strong></a>, <a href="?herb=128"><strong>California Poppy</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a> leaf and flower, <a href="?herb=13"><strong>Holy Basil</strong></a>, and <a href="?herb=45"><strong>Marshmallow</strong></a>. In traditional Hibiscus Refresher with <a href="?herb=2233"><strong>Hibiscus</strong></a>, clove, <a href="?herb=124"><strong>Ginger</strong></a>, orange peel, and <a href="?herb=73"><strong>Hawthorn</strong></a> L/F. In Red Drank with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>, clove, and honey/brown sugar. Warming carminative approach: marshmallow cold infusion + Cinnamon + <a href="?herb=127"><strong>Cardamom</strong></a> first.$$
WHERE common_name = 'Cinnamon';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cinnamon Bark</strong> (Cassia cinnamon, Cinnamomum aromaticum) is the common market cinnamon, identifiable by its very hard bark. <strong>High coumarin levels - avoid long-term use, especially for those with liver issues.</strong> Prefer Ceylon (<a href="?herb=167"><strong>Cinnamon</strong></a>, Cinnamomum verum) for medicinal use.$$
WHERE common_name = 'Cinnamon Bark';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Clary Sage increases effects of alcohol intoxication - hazardous as EO/hydrosol.</strong>$$
WHERE common_name = 'Clary Sage';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cleavers</strong> (Galium aparine), sticky like velcro and a spring green, is a <strong>lymphatic</strong>, <strong>diuretic</strong>, <strong>vulnerary</strong>, <strong>nutritive</strong>, <strong>anti-inflammatory</strong>, <strong>mild astringent</strong>, and <strong>lymph alterative</strong> - the herbalist's "badge" and "strainer for your body." A great full-body lymphatic tonic that moves toxins and byproducts of cellular metabolism and infection via the lymph system; a <strong>lymphagogue</strong> for accumulation with aging. Specific affinity for the upper third of the body and especially the neck, throat, and <strong>tonsils</strong> - alongside <a href="?herb=39"><strong>Figwort</strong></a> and <a href="?herb=981"><strong>Red Root</strong></a> for organ-specific lymphatic affinities. Used for <strong>sore throat</strong>, <strong>rheumatoid arthritis</strong> (promotes lymph circulation, not blood), <strong>autoimmune disease with ECM and Fibromyalgia</strong> (gentle lymphatic alongside <a href="?herb=198"><strong>Violet</strong></a>), <strong>common cold</strong>, <strong>influenza</strong>, and as a lymph alterative for <strong>hot constitution</strong>. As a <strong>urinary diuretic</strong>, removes excess water and sodium; a <strong>lymphatic herb for the urinary system</strong>; in kidney/bladder tonics with <a href="?herb=122"><strong>Dandelion</strong></a> leaf, <a href="?herb=58"><strong>Goldenrod</strong></a>, <a href="?herb=118"><strong>Bladderwrack</strong></a>, and watermelon in season. For chemo/cancer support: removes metabolic waste and radiation chemicals in tea; in anti-cancer formula 2 (more intense, used in stages after formula 1). Listed among hepatics/lymphatics for elimination and detox alongside <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, and <a href="?herb=37"><strong>Yellow Dock</strong></a>. For stroke recovery patient (hypertension, atrial fibrillation, stage 4 CKD) alongside <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, and <a href="?herb=178"><strong>Oat</strong></a> Straw - meds in the morning and evening, herbs in the midday. <strong>Caution with blood pressure - use with care when combined with linden, nettle, oat straw.</strong> With <a href="?herb=122"><strong>Dandelion</strong></a> and <a href="?herb=22"><strong>Burdock</strong></a> as poultice for <strong>breast cysts</strong>. Also noted as a possible preparation in tequila. Preparation: blend fresh in a blender, squeeze, preserve in alcohol or freeze.$$
WHERE common_name = 'Cleavers';
